def find_insert_position(sorted_values, target):
    """Return the index where target should be inserted to keep the list sorted.

    If target is already present, return the index of its FIRST occurrence.
    """
    low = 0
    high = len(sorted_values)
    while low < high:
        mid = (low + high) // 2
        if sorted_values[mid] < target:
            low = mid + 1
        else:
            high = mid
    return low

def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted(intervals, key=lambda interval: interval[0])
    merged = [[sorted_intervals[0][0], sorted_intervals[0][1]]]

    for start, end in sorted_intervals[1:]:
        last = merged[-1]
        if start <= last[1]:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])

    return merged

package pipeline

import "sync"

// FanIn runs fn over every input concurrently and returns the results in the
// same order as the inputs.
func FanIn(inputs []int, workers int, fn func(int) int) []int {
	out := make([]int, len(inputs))

	if len(inputs) == 0 {
		return out
	}

	if workers <= 0 {
		for i := range inputs {
			out[i] = fn(inputs[i])
		}
		return out
	}

	if workers > len(inputs) {
		workers = len(inputs)
	}

	jobs := make(chan int)
	var wg sync.WaitGroup

	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				out[i] = fn(inputs[i])
			}
		}()
	}

	for i := range inputs {
		jobs <- i
	}
	close(jobs)

	wg.Wait()
	return out
}

