import "container/list"

// LRU is a fixed-capacity least-recently-used cache.
type LRU struct {
	capacity int
	items    map[string]*list.Element
	order    *list.List
}

type entry struct {
	key   string
	value int
}

// NewLRU creates a new LRU cache with the given capacity.
// If capacity is negative, it is treated as zero.
func NewLRU(capacity int) *LRU {
	if capacity < 0 {
		capacity = 0
	}
	return &LRU{
		capacity: capacity,
		items:    make(map[string]*list.Element),
		order:    list.New(),
	}
}

// Get returns the value for key and marks it as most recently used.
func (c *LRU) Get(key string) (int, bool) {
	if c == nil || c.capacity <= 0 {
		return 0, false
	}

	elem, ok := c.items[key]
	if !ok {
		return 0, false
	}

	c.order.MoveToFront(elem)
	return elem.Value.(entry).value, true
}

// Put inserts or updates a key/value pair.
// If the cache is full, the least recently used entry is evicted.
func (c *LRU) Put(key string, value int) {
	if c == nil || c.capacity <= 0 {
		return
	}

	if elem, ok := c.items[key]; ok {
		c.order.MoveToFront(elem)
		elem.Value = entry{key: key, value: value}
		return
	}

	if c.order.Len() == c.capacity {
		oldest := c.order.Back()
		if oldest != nil {
			c.order.Remove(oldest)
			delete(c.items, oldest.Value.(entry).key)
		}
	}

	c.items[key] = c.order.PushFront(entry{key: key, value: value})
}

// Len returns the number of entries currently in the cache.
func (c *LRU) Len() int {
	if c == nil {
		return 0
	}
	return len(c.items)
}

export function groupConsecutive(values: number[]): number[][] {
  const groups: number[][] = [];
  let current: number[] = [];

  for (const value of values) {
    if (current.length > 0 && value === current[current.length - 1] + 1) {
      current.push(value);
    } else {
      if (current.length > 0) {
        groups.push(current);
      }
      current = [value];
    }
  }

  if (current.length > 0) {
    groups.push(current);
  }

  return groups;
}

export type Fetcher = (id: string) => Promise<{ id: string; parent: string | null }>;

export async function ancestry(fetch: Fetcher, start: string): Promise<string[]> {
  const seen = new Set<string>();
  const chain: string[] = [];
  let id = start;

  while (true) {
    if (seen.has(id)) {
      throw new Error("cycle detected");
    }

    seen.add(id);
    chain.push(id);

    if (chain.length > 50) {
      throw new Error("chain too long");
    }

    const node = await fetch(id);

    if (node.parent === null) {
      return chain;
    }

    id = node.parent;
  }
}

using System;
using System.Collections.Generic;

public static class Ledger
{
    // Returns, for each account, the running balance after every entry, and the
    // final balance. Entries are (account, delta) in chronological order.
    public static (Dictionary<string, List<int>> Running, Dictionary<string, int> Final, double AverageDelta)
        Summarise(IEnumerable<(string Account, int Delta)> entries)
    {
        var totals = new Dictionary<string, int>();
        var running = new Dictionary<string, List<int>>();
        long deltaSum = 0;
        int deltaCount = 0;

        if (entries != null)
        {
            foreach (var e in entries)
            {
                if (!totals.TryGetValue(e.Account, out int current))
                {
                    current = 0;
                    totals[e.Account] = current;
                    running[e.Account] = new List<int>();
                }

                current += e.Delta;
                totals[e.Account] = current;
                running[e.Account].Add(current);

                deltaSum += e.Delta;
                deltaCount++;
            }
        }

        double averageDelta = deltaCount == 0 ? 0.0 : (double)deltaSum / deltaCount;

        return (Running: running, Final: totals, AverageDelta: averageDelta);
    }
}

public class TelemetrySender
{
    private readonly NetworkManager _networkManager;

    public TelemetrySender(NetworkManager networkManager)
    {
        _networkManager = networkManager;
    }

    public void Send(string opcode, string payload)
    {
        if (opcode != null && opcode.Length > 8)
        {
            opcode = opcode.Substring(0, 8);
        }

        string frame = _networkManager.Encode(opcode ?? string.Empty, payload ?? string.Empty);
        _networkManager.Enqueue(frame);
    }
}

public static class FrameUtil
{
    public static int CountZeroes(FrameBuffer buffer)
    {
        int zeroes = 0;

        for (int i = 0; i < buffer.Count; i++)
        {
            if (buffer.Get(i) == 0)
            {
                zeroes++;
            }
        }

        return zeroes;
    }
}
